// FB1 — Federal budget accounting (15)
add("FB1","easy","definition","identify_budget_deficit","When federal outlays exceed federal revenues during a fiscal year, what is the result?","A budget deficit",["A budget surplus","A balanced budget","A reduction in gross debt"],"A deficit occurs because annual outlays are greater than annual revenues.");
add("FB1","easy","definition","identify_budget_surplus","Which fiscal position exists when annual federal revenues exceed annual outlays?","A budget surplus",["A budget deficit","A balanced budget","A debt rollover"],"Revenues greater than outlays produce a positive budget balance, called a surplus.");
add("FB1","easy","interpretation","distinguish_revenue_from_borrowing","Why is federal borrowing not classified as federal revenue in budget accounting?","Borrowing finances a shortfall rather than providing receipts from taxes or other revenue sources",["Borrowing is counted only when interest rates fall","Borrowing is a transfer payment to households","Borrowing is included in government purchases in GDP"],"Debt issuance supplies financing, but it does not turn the borrowed funds into budget revenue.");
add("FB1","medium","calculation","calculate_budget_balance","Federal revenues are $4.8 trillion and outlays are $6.2 trillion. Using revenues minus outlays, what is the budget balance?","−$1.4 trillion",["+$1.4 trillion","−$11.0 trillion","+$11.0 trillion"],"Revenues minus outlays equals $4.8 trillion minus $6.2 trillion, or −$1.4 trillion, a deficit.");
add("FB1","medium","calculation","interpret_budget_balance_sign","A federal budget balance is reported as +$120 billion. What does the positive sign mean?","Revenues exceed outlays by $120 billion",["Outlays exceed revenues by $120 billion","Federal debt equals $120 billion","Borrowing increased by exactly $120 billion"],"Under the stated revenues-minus-outlays convention, a positive balance is a surplus.");
add("FB1","medium","calculation","calculate_deficit_magnitude","Federal revenues total $5.1 trillion and outlays total $5.9 trillion. What is the deficit expressed as a positive magnitude?","$0.8 trillion",["−$0.8 trillion","$5.1 trillion","$11.0 trillion"],"Outlays exceed revenues by $0.8 trillion, so the deficit magnitude is reported as positive $0.8 trillion.");
add("FB1","hard","integration","reconcile_balance_conventions","One table reports a budget balance of −$900 billion; another describes a deficit of $900 billion. Are the reports consistent?","Yes; one gives the signed balance and the other gives the positive deficit magnitude",["No; a deficit must always carry a negative sign","No; a balance and a deficit cannot use the same number","Yes; both describe a $900 billion surplus"],"A negative revenues-minus-outlays balance and a positive deficit magnitude can describe the same shortfall.");
add("FB1","hard","calculation","compare_budget_balances","Revenues rise from $4.9 trillion to $5.2 trillion while outlays rise from $6.0 trillion to $6.1 trillion. How does the budget balance change?","It improves by $0.2 trillion, though the budget remains in deficit",["It worsens by $0.2 trillion","It improves by $0.3 trillion and becomes a surplus","It is unchanged because both revenues and outlays rise"],"The balance moves from −$1.1 trillion to −$0.9 trillion, an improvement of $0.2 trillion.");
add("FB1","elite","integration","diagnose_rounded_budget_data","A published table rounds revenues to $5.6 trillion, outlays to $7.4 trillion, and the deficit to $1.9 trillion. Why need the rounded entries not subtract exactly?","Each displayed figure may have been rounded independently from more precise underlying values",["A deficit is unrelated to revenues and outlays","Borrowing is automatically added to both revenues and outlays","The table must be using calendar years for the deficit only"],"Independent rounding can make displayed components differ slightly from an identity calculated with unrounded values.");
add("FB1","elite","integration","infer_missing_budget_component","A fiscal-year budget has a $0.6 trillion surplus and $5.4 trillion in outlays. What revenues are consistent with those figures?","$6.0 trillion",["$4.8 trillion","$5.4 trillion","$6.6 trillion"],"A surplus equals revenues minus outlays, so revenues must be $5.4 trillion plus $0.6 trillion.");
add("FB1","legendary","integration","evaluate_budget_accounting_claim","A headline says, “Borrowing rose, so federal revenues must have risen by the same amount.” What is the central accounting error?","It treats deficit financing as revenue",["It treats outlays as a stock","It subtracts revenues from GDP","It assumes every surplus raises borrowing"],"Borrowing finances a gap between revenues and outlays; it is not itself a revenue category.");
add("FB1","easyBoss","application","identify_budget_position","Annual federal revenues equal $5.0 trillion and outlays equal $5.3 trillion. Which fiscal position is shown?","A $0.3 trillion deficit",["A $0.3 trillion surplus","A balanced budget","A $5.3 trillion debt stock"],"Outlays exceed revenues by $0.3 trillion, so the annual budget is in deficit.");
add("FB1","mediumBoss","integration","interpret_projected_budget_position","According to CBO's February 2026 baseline, FY2026 revenues are projected at about $5.6 trillion and outlays at about $7.4 trillion. What fiscal position is projected?","A deficit because projected outlays exceed projected revenues",["A surplus because projected revenues are positive","A balanced budget because both values are projections","A debt stock of $1.8 trillion"],"CBO projects outlays above revenues, which is a deficit; the published rounded deficit is about $1.9 trillion.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB1","repairQuestions","definition","identify_budget_position","Federal revenues are $5 trillion and outlays are $6 trillion. Is the budget in surplus or deficit?","Deficit",["Surplus","Balanced","Debt-free"],"Outlays exceed revenues by $1 trillion, so the federal budget is in deficit.");
add("FB1","bridgeQuestions","bridge","connect_balance_to_borrowing","A federal budget records revenues below outlays. What financing issue follows from that accounting result?","The government must finance the shortfall, commonly through borrowing",["The shortfall automatically becomes tax revenue","Government purchases must equal zero","The existing debt stock disappears"],"A deficit is an annual financing gap; borrowing is a common way to cover it.");

// FB2 — Deficit versus debt (17)
add("FB2","easy","definition","classify_flow_and_stock","Which statement correctly classifies the federal deficit and federal debt?","The deficit is an annual flow; debt is an accumulated stock",["Both are annual flows","Both are accumulated stocks","The deficit is a stock; debt is a flow"],"A deficit is measured over a period, while debt is measured at a point in time.");
add("FB2","easy","interpretation","smaller_deficit_not_lower_debt","The federal deficit falls from $1.8 trillion to $1.2 trillion. Which conclusion necessarily follows?","Annual borrowing needs are smaller under the simplified conditions, but debt can still rise",["Federal debt necessarily falls by $0.6 trillion","The budget has moved into surplus","Existing federal debt has been eliminated"],"A smaller positive deficit adds less to debt than before, but it still represents a shortfall.");
add("FB2","easy","interpretation","balanced_budget_existing_debt","What does a balanced annual federal budget imply about existing federal debt?","It stops a new annual deficit but does not erase the existing debt stock",["It immediately reduces debt to zero","It proves the prior year had a surplus","It converts all debt into revenue"],"Balancing annual revenues and outlays addresses the current flow, not the accumulated stock.");
add("FB2","medium","application","infer_debt_direction_from_deficit","Assume a $400 billion deficit is entirely financed by borrowing and there are no other financing adjustments. What happens to federal debt?","It rises by $400 billion",["It falls by $400 billion","It is unchanged","It becomes exactly $400 billion"],"Under the stated simplifying assumption, borrowing to finance the deficit adds $400 billion to the debt stock.");
add("FB2","medium","application","distinguish_reduced_deficit_from_surplus","A deficit declines from $900 billion to $500 billion. Has the budget moved into surplus?","No; outlays still exceed revenues by $500 billion",["Yes; the deficit fell by $400 billion","Yes; any deficit reduction is a surplus","No; a surplus is impossible when revenues rise"],"Reducing a deficit changes its size, but a surplus requires revenues to exceed outlays.");
add("FB2","medium","interpretation","surplus_and_debt","Assume there are no other financing adjustments. How can an annual surplus affect federal debt?","The surplus can be used to reduce the debt stock",["It must increase debt by the surplus amount","It converts debt from a stock into a flow","It leaves debt unchanged by definition"],"With revenues above outlays, the excess can reduce outstanding borrowing under the stated assumption.");
add("FB2","hard","integration","multi_year_deficit_debt","Debt begins at $18.0 trillion. Deficits of $0.8 trillion and $0.5 trillion follow in two years. Assuming borrowing finances each deficit and no other adjustments occur, what is debt after year two?","$19.3 trillion",["$17.7 trillion","$18.5 trillion","$20.6 trillion"],"The two deficits add $1.3 trillion to the initial $18.0 trillion debt stock.");
add("FB2","hard","interpretation","separate_flow_stock_headline","A report says debt reached $25 trillion while the year's deficit was $1 trillion. Why are the figures not contradictory?","Debt is the accumulated stock; the deficit is one year's flow",["The deficit excludes all federal outlays","Debt measures only interest payments","A deficit and debt must always be equal"],"The annual deficit is one contributor to the much larger accumulated debt stock.");
add("FB2","hard","integration","deficit_debt_financing_caution","Why is the reported annual deficit not always identical to the measured change in federal debt?","Cash balances, timing, and other financing adjustments can affect the measured debt change",["Deficits never require financing","Debt is measured only once per decade","Federal revenues are excluded from deficit calculations"],"Real Treasury financing includes adjustments beyond the simplified classroom assumption that all deficit financing maps one-for-one into debt.");
add("FB2","elite","integration","reconcile_smaller_deficit_rising_debt","A deficit falls from $1.4 trillion to $0.9 trillion while debt rises. Which explanation is coherent?","The government still runs a deficit, so debt can keep rising even though it rises more slowly",["A smaller deficit is necessarily a surplus","Debt can rise only when the deficit grows","The debt increase proves revenues exceeded outlays"],"A reduced deficit remains positive borrowing need; it need not reverse the direction of the debt stock.");
add("FB2","elite","integration","evaluate_debt_elimination_claim","A proposal balances the budget beginning next year. Which claim goes beyond what that fact establishes?","The existing federal debt will disappear next year",["No new deficit is planned next year","Projected revenues equal projected outlays next year","The annual budget position would improve if it was previously in deficit"],"A balanced flow prevents new deficit accumulation but does not repay the accumulated stock immediately.");
add("FB2","legendary","integration","reconcile_three_fiscal_facts","The deficit becomes smaller, nominal debt rises, and debt-to-GDP falls. Which combination can explain all three facts?","A positive but smaller deficit adds to debt while nominal GDP grows faster than debt",["A surplus adds to debt while GDP shrinks","Debt falls faster than GDP while the deficit grows","A balanced budget erases debt while GDP is unchanged"],"The deficit can still add to nominal debt, while faster GDP growth lowers the debt ratio.");
add("FB2","legendary","integration","diagnose_stock_flow_comparison","An analyst divides the debt stock at one date by one month's deficit and calls the result a debt-to-deficit growth rate. What is the main problem?","The calculation compares a stock with a partial-period flow without a meaningful common basis",["Debt and deficits must be expressed in different currencies","Monthly deficits are always surpluses","Debt cannot be compared with any fiscal flow"],"Stocks and flows can be related, but the period and interpretation must be specified; this ratio is not a growth rate.");
add("FB2","finalBoss","integration","deficit_debt_mastery","The annual deficit narrows from $1.5 trillion to $0.7 trillion. Assuming each deficit is financed by borrowing, which statement is correct?","Debt rises in both years, but by less in the second year",["Debt falls by $0.8 trillion in the second year","The second year has a $0.8 trillion surplus","Debt is unchanged because the deficit narrowed"],"Both years have positive deficits, so debt rises under the assumption; only the size of the addition falls.");
add("FB2","legendaryBoss","integration","flow_stock_ratio_synthesis","CBO's February 2026 baseline projects a $1.9 trillion FY2026 deficit and debt held by the public equal to 101 percent of GDP at year-end. What distinction is essential?","The deficit is a fiscal-year flow, whereas the debt ratio describes a year-end stock relative to GDP",["Both numbers are realized calendar-year flows","The debt ratio is the share of outlays financed by taxes","The deficit is the government's total accumulated debt"],"The CBO figures describe different economic objects and are explicitly projections.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB2","repairQuestions","definition","distinguish_deficit_and_debt","Which measure describes how much outlays exceed revenues during one year?","The deficit",["The debt stock","Debt-to-GDP","Intragovernmental holdings"],"A deficit is measured over a year; debt is the accumulated amount outstanding at a date.");
add("FB2","bridgeQuestions","bridge","connect_deficit_to_debt","A government runs a deficit and finances it entirely by borrowing. What happens next in the simplified example?","The debt stock increases",["The debt stock is erased","The budget becomes balanced automatically","The deficit becomes revenue"],"Borrowing to cover the annual shortfall adds to accumulated debt under the stated simplification.");

// FB3 — Public saving (11)
add("FB3","easy","definition","define_public_saving_variables","In the identity public saving = T − G, what must T represent in this bank?","Net tax revenue, including relevant receipts net of transfers",["Total federal outlays","Gross tax collections before any transfers","The federal debt stock"],"The shorthand is valid here only when T is defined net of transfers and G is government purchases.");
add("FB3","easy","interpretation","interpret_negative_public_saving","Under public saving = T − G, with T defined as net tax revenue and G as government purchases, what does negative public saving mean?","Net tax revenue is less than government purchases",["Private saving must be negative","GDP must be falling","The government has no outstanding debt"],"Public saving is negative when net tax revenue T is below government purchases G.");
add("FB3","medium","calculation","calculate_public_saving","Net tax revenue T is $3.2 trillion and government purchases G are $3.8 trillion. What is public saving?","−$0.6 trillion",["+$0.6 trillion","$3.2 trillion","$7.0 trillion"],"Using the stated identity, public saving is T minus G, or $3.2 trillion minus $3.8 trillion.");
add("FB3","medium","calculation","calculate_positive_public_saving","Suppose T is explicitly defined as net tax revenue and equals $2.9 trillion, while government purchases G equal $2.5 trillion. What is public saving?","+$0.4 trillion",["−$0.4 trillion","$2.5 trillion","$5.4 trillion"],"With the variables defined, T − G equals +$0.4 trillion, indicating positive public saving.");
add("FB3","hard","integration","avoid_public_saving_convention_error","A table gives total federal revenues of $5 trillion and total outlays, including transfers and interest, of $6 trillion. What should revenues minus outlays be called?","A $1 trillion federal budget deficit",["Public saving of −$1 trillion under T − G","Private saving of $1 trillion","Government purchases of $6 trillion"],"Total revenues minus total outlays is the budget balance. In the T − G public-saving shorthand, T must be net tax revenue and G must be government purchases.");
add("FB3","hard","integration","connect_budget_deficit_public_saving","Holding the relevant definitions and other items fixed, what is the basic public-saving implication of a larger budget deficit?","Public saving is lower",["Public saving is necessarily higher","Private saving becomes zero by identity","Government purchases are no longer part of GDP"],"A wider fiscal shortfall reduces the government's contribution to national saving under the introductory accounting link.");
add("FB3","elite","integration","reconcile_budget_and_public_saving_measures","Why can a total-outlays budget balance and T − G public saving, where T is net tax revenue and G is government purchases, differ numerically?","Total outlays can include transfers and interest, while G in the stated identity means government purchases",["Public saving excludes all government receipts","Budget balances are stocks while public saving is always a stock","T always equals total outlays"],"The two calculations use different components unless the question defines them to be equivalent.");
add("FB3","easyBoss","application","identify_public_saving_sign","With T defined as net tax revenue and G as government purchases, T equals $800 billion and G equals $900 billion. What is public saving?","−$100 billion",["+$100 billion","$800 billion","$1.7 trillion"],"T − G equals −$100 billion, so public saving is negative.");
add("FB3","mediumBoss","integration","public_saving_boundary","Which statement uses the project's public-saving convention correctly?","T − G is public saving when T is net tax revenue, net of transfers, and G is government purchases",["Total revenues minus all federal outlays is always labeled T − G public saving","T means gross tax collections and G includes transfers","Public saving is the stock of federal debt"],"The notation is valid only when T is net tax revenue, net of transfers, and G is government purchases.");
add("FB3","repairQuestions","calculation","calculate_public_saving","T is net tax revenue of $700 billion and G is purchases of $600 billion. What is public saving?","+$100 billion",["−$100 billion","$600 billion","$1.3 trillion"],"Subtract government purchases from net tax revenue: $700 billion minus $600 billion equals +$100 billion.");
add("FB3","bridgeQuestions","bridge","connect_public_to_national_saving","Why does negative public saving matter beyond the federal budget?","Public saving is one component of national saving",["It directly fixes the exchange rate","It makes private saving impossible","It determines the money supply by definition"],"Lower public saving reduces one component of national saving, providing a bridge to the later saving-and-investment framework.");

// FB4 — Federal revenues and outlays (11)
add("FB4","easy","definition","classify_transfer_outlay","A Social Security benefit payment is best classified as what from the federal budget perspective?","A transfer payment and a federal outlay",["Federal revenue","Government purchases in GDP when paid","Intragovernmental debt"],"The payment is an outlay that transfers income; it is not a purchase of current output when issued.");
add("FB4","easy","definition","classify_government_purchase","The federal government buys newly produced rescue equipment. How is the transaction classified?","A federal outlay and government purchase",["A transfer payment only","Federal revenue","Debt held by the public"],"Paying for newly produced equipment is both an outlay and government purchases in GDP.");
add("FB4","medium","application","distinguish_mandatory_discretionary","Which statement accurately distinguishes mandatory and discretionary spending?","Mandatory spending follows eligibility or payment rules in law; discretionary spending is provided through appropriations",["Mandatory spending is literally impossible to change","Discretionary spending is economically unimportant","All transfer payments are discretionary"],"The labels describe budget processes, not whether spending matters or can ever be changed by law.");
add("FB4","medium","application","classify_interest_outlay","Interest paid on outstanding federal debt belongs in which budget category?","Federal outlays for net interest, not government purchases in GDP",["Federal revenue","A transfer classified as government purchases","Intragovernmental holdings"],"Interest outlays service prior borrowing; they are not purchases of newly produced goods and services.");
add("FB4","hard","integration","purchase_transfer_budget_gdp","A benefit payment and a purchase of new federal vehicles are both outlays. What distinguishes their GDP treatment?","Only the vehicle purchase enters G directly when paid",["Both enter G directly because both are outlays","Neither can enter GDP","Only the benefit payment enters G directly"],"A transfer redistributes income, whereas the vehicle purchase pays for current production.");
add("FB4","hard","integration","classify_revenue_and_borrowing","Taxes raise $4.7 trillion and borrowing supplies $1.1 trillion. Which amount is federal revenue?","$4.7 trillion",["$1.1 trillion","$5.8 trillion","Neither amount"],"Taxes are receipts; borrowing finances the gap and is not recorded as revenue.");
add("FB4","elite","integration","evaluate_spending_label_claim","A speaker calls all discretionary outlays “optional” and all mandatory outlays “uncontrollable.” What is wrong with the claim?","The categories describe funding rules, and either category can be changed through legislation",["Discretionary outlays are never appropriated","Mandatory programs never make transfers","Interest outlays are federal revenues"],"Process labels do not settle importance, desirability, or whether future law can alter spending.");
add("FB4","finalBoss","integration","classify_budget_transactions","The government collects payroll taxes, sends pension benefits, and buys medical equipment. Which classification is correct?","Taxes are revenue; benefits and equipment are outlays; only the equipment is government purchases in GDP",["All three are revenues","Both benefits and equipment are government purchases in GDP","Payroll taxes are borrowing and benefits are revenue"],"Budget and GDP classifications overlap but are not identical: transfers are outlays without entering G when paid.");
add("FB4","legendaryBoss","integration","interpret_cbo_outlay_categories","CBO's February 2026 baseline classifies projected FY2026 outlays as mandatory, discretionary, or net interest. What is the sound interpretation?","The labels describe budget treatment; they do not mean mandatory spending is unchangeable or discretionary spending is trivial",["The categories are realized calendar-year revenues","Only discretionary outlays count in the federal budget","Net interest is debt held by the public"],"CBO reports projected fiscal-year outlays by category; the labels describe their budget treatment, not their importance.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB4","repairQuestions","definition","distinguish_purchase_transfer","Which transaction is a government purchase rather than a transfer?","The federal purchase of new computers",["A pension benefit payment","An unemployment benefit payment","An interest payment on debt"],"Buying current goods is a government purchase; benefits and interest are outlays but not G purchases.");
add("FB4","bridgeQuestions","bridge","connect_outlay_to_gdp","A federal benefit payment is an outlay but not government purchases in GDP when paid. When can it affect measured GDP?","When the recipient later buys newly produced final goods or services",["When the Treasury labels it mandatory","Immediately because every outlay is G","Only when federal debt falls"],"The transfer itself is not production; later consumption of current final output can enter GDP.");

// FB5 — Measures of federal debt (11)
add("FB5","easy","definition","identify_debt_held_public","Which measure covers federal debt held by entities outside the federal government?","Debt held by the public",["Intragovernmental holdings","The annual deficit","Net interest outlays"],"Debt held by the public is the portion held outside the federal government under Treasury's definition.");
add("FB5","easy","definition","identify_intragovernmental_holdings","What are intragovernmental holdings?","Federal securities held by government trust funds and other government accounts",["All Treasury securities held by foreign governments","The annual excess of outlays over revenues","Only currency held by the Federal Reserve"],"They are claims held within federal government accounts, not debt held by outside investors.");
add("FB5","medium","calculation","calculate_total_public_debt","Debt held by the public is $24 trillion and intragovernmental holdings are $6 trillion. What is total public debt outstanding?","$30 trillion",["$18 trillion","$24 trillion","$144 trillion"],"Treasury defines total public debt outstanding as the sum of the two components.");
add("FB5","medium","interpretation","require_debt_measure_label","Why is a statement that “federal debt is $X” incomplete?","Different federal debt measures can have different values and meanings",["Debt can never be measured in dollars","Every debt measure equals the annual deficit","Only GDP can be used to describe debt"],"The statement should identify whether it means debt held by the public, total public debt, or another specified measure.");
add("FB5","hard","integration","compare_debt_measures","A report lists debt held by the public at $25 trillion and total public debt outstanding at $32 trillion. What can be inferred?","The difference reflects intragovernmental holdings under the stated Treasury definitions",["The $7 trillion difference is the annual deficit","The two figures must refer to different countries","Debt held by the public includes all intragovernmental holdings"],"Total public debt combines debt held by the public with intragovernmental holdings.");
add("FB5","hard","interpretation","debt_limit_measure_precision","Why should debt subject to the statutory limit not automatically be substituted for debt held by the public?","The measures are defined for different purposes and need not include the same obligations",["The debt limit is an annual flow","Debt held by the public excludes all Treasury securities","Both measures are always numerically identical"],"Debt measures have distinct legal and analytical boundaries, so the label must match the source.");
add("FB5","elite","integration","diagnose_two_release_comparison","Two releases report different debt values on the same date, but one labels debt held by the public and the other labels total public debt outstanding. What is the best conclusion?","The figures cannot be compared as though they were the same measure",["One release must be false","The difference is necessarily that day's deficit","The smaller figure must be intragovernmental holdings"],"Measure definitions must be aligned before interpreting a numerical difference.");
add("FB5","easyBoss","application","identify_gross_debt_components","Which expression gives the broad Treasury relationship for total public debt outstanding?","Debt held by the public plus intragovernmental holdings",["Debt held by the public minus revenues","Annual deficit plus net interest only","GDP plus federal outlays"],"Treasury's data dictionary defines total public debt as the sum of the two debt components.");
add("FB5","mediumBoss","interpretation","apply_treasury_debt_definition","Treasury's Debt to the Penny data list debt held by the public separately from intragovernmental holdings. Why?","They identify different holders and combine to form total public debt outstanding",["One is a flow and the other is GDP","Intragovernmental holdings are foreign-owned debt","Debt held by the public is a federal outlay"],"The data dictionary separates outside-government holdings from claims held by government accounts.",{dataSourceKey:"TREASURY-DEBT-TO-PENNY"});
add("FB5","repairQuestions","definition","distinguish_debt_measures","Which measure equals debt held by the public plus intragovernmental holdings?","Total public debt outstanding",["The annual deficit","Net interest outlays","Government purchases"],"Treasury defines total public debt outstanding as the sum of those two components.");
add("FB5","bridgeQuestions","bridge","connect_debt_measure_to_ratio","Treasury defines debt held by the public as a distinct debt measure. What additional quantity is needed to express that measure relative to the economy?","GDP for a matching period",["The annual inflation rate alone","Government purchases only","The number of Treasury securities"],"A debt-to-GDP ratio divides a specified debt stock by a compatible GDP measure.",{dataSourceKey:"TREASURY-DEBT-TO-PENNY"});

// FB6 — Debt-to-GDP (15)
add("FB6","easy","calculation","calculate_debt_to_gdp","Debt held by the public is $24 trillion and nominal GDP is $30 trillion. What is debt-to-GDP?","80 percent",["6 percent","24 percent","125 percent"],"Dividing $24 trillion by $30 trillion and multiplying by 100 gives 80 percent.");
add("FB6","easy","interpretation","interpret_debt_ratio","What does debt held by the public equal to 90 percent of GDP mean?","The specified debt stock is nine-tenths of one year's GDP",["Ninety percent of annual outlays are interest","The annual deficit equals 90 percent of GDP","GDP is 90 percent owned by the government"],"The ratio compares a debt stock at a date with the scale of annual economic output.");
add("FB6","medium","calculation","compare_nominal_debt_ratios","Two countries each have $2 trillion in public debt. Country A's GDP is $4 trillion; Country B's is $10 trillion. Which has the higher debt-to-GDP ratio?","Country A",["Country B","They have equal ratios","The comparison is impossible even with GDP"],"The ratios are 50 percent for A and 20 percent for B, so equal nominal debt implies different relative burdens.");
add("FB6","medium","interpretation","debt_gdp_growth_direction","Debt grows 5 percent while nominal GDP grows 8 percent. What happens to debt-to-GDP, other things equal?","It falls",["It rises by 13 percent","It rises because nominal debt rose","It is unchanged"],"The denominator grows faster than the numerator, so debt becomes a smaller share of GDP.");
add("FB6","medium","calculation","percentage_points_debt_ratio","Debt-to-GDP rises from 90 percent to 95 percent. How should the change be stated?","An increase of 5 percentage points",["An increase of exactly 5 percent","An increase of 95 percentage points","A decrease of 5 percentage points"],"Subtracting percentage levels gives a five-percentage-point increase; the percent change would be about 5.6 percent.");
add("FB6","hard","integration","simultaneous_debt_gdp_change","Debt rises from $20 trillion to $21 trillion while nominal GDP rises from $20 trillion to $22 trillion. What happens to debt-to-GDP?","It falls from 100 percent to about 95.5 percent",["It rises from 100 percent to 105 percent","It remains at 100 percent","It falls to about 50 percent"],"Debt grows 5 percent, but GDP grows 10 percent, reducing the ratio to approximately 21/22.");
add("FB6","hard","comparison","compare_two_economies_ratios","Economy A has $9 trillion in debt and $12 trillion in GDP. Economy B has $12 trillion in debt and $24 trillion in GDP. Which has the higher debt-to-GDP ratio?","Economy A",["Economy B","They are equal","Nominal debt alone makes comparison impossible after GDP is supplied"],"A's ratio is 75 percent, compared with 50 percent for B.");
add("FB6","hard","integration","infer_gdp_growth_from_ratio","Nominal debt rises, yet debt-to-GDP falls. What must be true under the stated comparison?","Nominal GDP grew proportionally faster than debt",["GDP necessarily fell","The annual budget necessarily had a surplus","Debt was reclassified as revenue"],"A falling ratio with a rising numerator requires the denominator to grow at a faster proportional rate.");
add("FB6","elite","integration","diagnose_nominal_debt_claim","A commentator says Economy B is in the weaker fiscal position because its nominal debt is larger than Economy A's. What evidence is missing?","Comparable GDP and a consistent debt measure",["The unemployment rate alone","Only the number of bondholders","A list of every federal agency"],"Relative comparisons require both economic scale and consistently defined debt measures.");
add("FB6","legendary","integration","reconcile_ratio_and_deficit","Debt-to-GDP falls while the government runs a deficit. Which statement is most accurate?","The deficit can raise nominal debt while sufficiently rapid nominal GDP growth lowers the ratio",["A deficit always raises the ratio","A falling ratio proves nominal debt fell","GDP growth cannot affect a debt ratio"],"The deficit concerns the debt numerator's direction, while denominator growth can dominate the ratio.");
add("FB6","legendary","integration","separate_percent_changes","Debt-to-GDP increases from 80 percent to 88 percent. Which statement is correct?","The ratio rose 8 percentage points, which is a 10 percent increase from its initial level",["The ratio rose 8 percent and 10 percentage points","The ratio rose 88 percentage points","The ratio rose 10 percentage points and 8 percent"],"The level change is 8 points; dividing 8 by the initial 80 gives a 10 percent relative increase.");
add("FB6","finalBoss","integration","debt_ratio_mastery","Country A's debt grows 4 percent and nominal GDP grows 7 percent. Country B's debt grows 6 percent and nominal GDP grows 3 percent. Which comparison is correct?","A's debt ratio tends to fall while B's tends to rise",["Both ratios rise because debt rises","Both ratios fall because GDP rises","A's ratio rises while B's falls"],"A's denominator grows faster than its numerator; B's numerator grows faster than its denominator.");
add("FB6","legendaryBoss","integration","interpret_cbo_debt_ratio_projection","CBO's February 2026 baseline projects debt held by the public at 101 percent of GDP in 2026 and 120 percent in 2036. What does the comparison imply?","The specified debt stock is projected to grow relative to the economy by 19 percentage points",["The annual deficit rises by exactly 19 percent","Debt held by the public is projected to fall in dollars","GDP is projected to become 120 percent federal debt"],"The ratio rises from 101 to 120 percent, a 19-percentage-point increase in the projected debt stock relative to GDP.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB6","repairQuestions","calculation","calculate_debt_to_gdp","Debt is $15 trillion and GDP is $20 trillion. What is debt-to-GDP?","75 percent",["25 percent","35 percent","133 percent"],"Divide debt by GDP: 15/20 equals 0.75, or 75 percent.");
add("FB6","bridgeQuestions","bridge","connect_cbo_ratio_to_measure","CBO projects debt held by the public at 101 percent of GDP in 2026. What must remain explicit when using that ratio?","Both the debt measure and the projected year",["Only the word debt","The value of intragovernmental holdings alone","A claim that the figure is already realized"],"The ratio identifies debt held by the public, the year, and its projected status.",{dataSourceKey:"CBO-2026-OUTLOOK"});

// FB7 — Interest costs and debt service (10)
add("FB7","easy","definition","distinguish_debt_interest","Which statement distinguishes federal debt from annual net interest outlays?","Debt is an outstanding stock; net interest is a fiscal-year outlay",["Both are annual revenue flows","Interest is the entire debt stock","Debt is a transfer payment measured each month"],"Outstanding debt is measured at a date, while net interest is paid over a budget period.");
add("FB7","easy","interpretation","identify_interest_cost_driver","Holding the debt stock fixed, what can raise annual interest costs in a simplified example?","A higher average interest rate",["A lower average interest rate","A smaller debt stock","A larger budget surplus with no rate change"],"With the stock held fixed, a higher effective rate raises the interest paid during the year.");
add("FB7","medium","calculation","calculate_simple_interest_cost","Assume, for illustration, that a $10 trillion debt stock carries a uniform 4 percent annual rate. What is the annual interest cost?","$0.4 trillion",["$4.0 trillion","$40 trillion","$0.04 trillion"],"Under the explicitly simplified assumption, 4 percent of $10 trillion is $0.4 trillion.");
add("FB7","medium","calculation","calculate_interest_share_outlays","Net interest outlays are $0.9 trillion and total outlays are $6.0 trillion. What share of outlays is net interest?","15 percent",["6 percent","9 percent","67 percent"],"Dividing $0.9 trillion by $6.0 trillion gives 0.15, or 15 percent.");
add("FB7","hard","integration","interest_feedback_budget","Why can rising interest outlays contribute to future deficits, other things equal?","They increase federal outlays without directly purchasing current public services",["They automatically increase tax revenue by the same amount","They reduce the debt stock immediately","They are excluded from all federal outlays"],"Higher interest costs widen the gap between revenues and outlays unless offset elsewhere.");
add("FB7","elite","integration","avoid_single_rate_assumption","Why is it misleading to multiply the entire actual federal debt by one market rate without qualification?","Outstanding securities have different rates and maturities, so one rate is only a simplifying assumption",["Federal debt never pays interest","Interest costs depend only on GDP","Every Treasury security matures daily"],"A classroom uniform-rate calculation can illustrate the channel but does not describe the actual debt portfolio exactly.");
add("FB7","easyBoss","application","distinguish_interest_from_principal","A government owes $20 trillion and pays $800 billion in net interest during the year. Which is the stock?","The $20 trillion debt",["The $800 billion interest outlay","Both figures are annual flows","Neither figure"],"The debt is outstanding at a date; the interest payment is an annual flow.");
add("FB7","mediumBoss","integration","interpret_cbo_interest_projection","CBO's February 2026 baseline projects net interest outlays above $1.0 trillion in FY2026, up from $970 billion in FY2025. What is the valid interpretation?","The annual projected interest outlay rises; the figures are not the debt stock itself",["Federal debt is projected at exactly $1.0 trillion","The values are realized calendar-year revenues","The annual deficit must equal the interest outlay"],"CBO reports projected fiscal-year interest flows, distinct from the accumulated debt stock.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB7","repairQuestions","calculation","calculate_simple_interest_cost","Under a simplifying assumption, debt is $5 trillion and the annual rate is 2 percent. What is the interest cost?","$0.1 trillion",["$1.0 trillion","$2.5 trillion","$10 trillion"],"Two percent of $5 trillion is $0.1 trillion, or $100 billion.");
add("FB7","bridgeQuestions","bridge","connect_interest_to_budget_balance","If net interest outlays rise while revenues and all other outlays are unchanged, what happens to the budget balance?","It moves toward a larger deficit or smaller surplus",["It improves automatically","It becomes debt-to-GDP","It is unaffected because interest is not an outlay"],"Higher interest outlays reduce revenues minus total outlays when everything else is fixed.");

// FB8 — Persistent deficits and government borrowing (11)
add("FB8","easy","interpretation","persistent_deficits_debt","What generally happens when the federal government runs persistent deficits?","Repeated financing shortfalls tend to add to accumulated debt",["Existing debt is automatically erased","Every deficit becomes a surplus later","Government purchases are removed from GDP"],"Deficits are recurring gaps that generally require financing and add to the debt stock.");
add("FB8","easy","interpretation","deficit_borrowing_chain","Which sequence is correct at an introductory level?","Deficit, financing through borrowing, larger accumulated debt",["Surplus, lower revenue, larger deficit by definition","Debt, automatic revenue, no outlays","Borrowing, smaller debt, larger surplus by identity"],"Borrowing commonly finances a deficit, and repeated borrowing adds to outstanding debt.");
add("FB8","medium","application","calculate_persistent_deficit_debt","Debt is initially $12 trillion. Three annual deficits of $0.4 trillion are fully financed by borrowing, with no other adjustments. What is debt afterward?","$13.2 trillion",["$10.8 trillion","$12.4 trillion","$14.4 trillion"],"Three deficits add $1.2 trillion to the starting stock under the simplifying assumptions.");
add("FB8","medium","interpretation","borrowing_not_revenue","Why does issuing debt not close a deficit by increasing measured revenue?","Borrowing finances the deficit but is not a budget receipt",["Borrowing counts as mandatory spending","Debt issuance reduces outlays to zero","All borrowing is intragovernmental"],"Financing explains how the shortfall is covered, not how revenues and outlays are classified.");
add("FB8","hard","integration","deficit_public_saving_chain","Which chain stays within the intended Principles-level boundary?","A larger deficit lowers public saving and increases government borrowing, all else equal",["A larger deficit fixes the equilibrium real interest rate by law","A deficit always eliminates private investment","A surplus necessarily causes an exchange-rate depreciation"],"The bank introduces the saving and borrowing link but leaves market equilibrium and graphical crowding out to other concepts.");
add("FB8","hard","integration","borrowing_consequence_conditional","Which statement about sustained government borrowing is appropriately conditional?","It can put upward pressure on interest rates and reduce some private investment",["It always eliminates all private investment","It can never affect broader financial conditions","It guarantees faster economic growth"],"The possible effect depends on economic conditions; it is not an unconditional outcome.");
add("FB8","legendary","integration","evaluate_borrowing_tradeoff_claim","A claim says all borrowing is harmful because it raises debt. What is the best economic response?","Debt and interest costs matter, but the full assessment also depends on circumstances and what the borrowing finances",["Borrowing has no costs under any circumstances","Any deficit proves national saving is zero","Economics can determine the only acceptable fiscal philosophy"],"Positive analysis identifies accounting effects and conditional tradeoffs without turning them into a universal normative verdict.");
add("FB8","finalBoss","integration","persistent_deficit_mastery","Over four years, the government runs progressively smaller but still positive deficits. Under simplified borrowing finance, what happens?","Debt continues to rise, though the annual additions become smaller",["Debt falls because each deficit is smaller","Debt becomes zero in the fourth year","Public saving necessarily becomes positive"],"A smaller deficit is still a deficit; it adds less to debt but does not reverse the stock by itself.");
add("FB8","legendaryBoss","integration","boundary_synthesis","A larger deficit reduces public saving. Which next statement is appropriate here without completing the loanable-funds model?","Greater government borrowing can put upward pressure on interest rates and private investment",["The exact equilibrium real interest rate must fall by the deficit percentage","A loanable-funds graph must shift by a fixed distance","Foreign capital inflows necessarily equal the deficit"],"The introductory link is conditional; full market equilibrium and open-economy analysis belong to later concepts.");
add("FB8","repairQuestions","definition","connect_deficit_borrowing","A government has outlays above revenues. What commonly finances the shortfall?","Government borrowing",["A budget surplus","Lower accumulated debt by definition","Government purchases becoming revenue"],"Borrowing is a common way to finance the annual gap between outlays and revenues.");
add("FB8","bridgeQuestions","bridge","connect_borrowing_to_phase_two","A larger deficit lowers public saving, all else equal. What broader topic should be studied next to trace the full financial-market effect?","Saving, investment, and the loanable-funds market",["The consumer price index only","Monopoly pricing","The production-possibilities frontier only"],"The complete interest-rate and investment mechanism belongs in the later saving-and-investment concept.");

// FB9 — Real-world fiscal-data interpretation (7; all official-data records)
add("FB9","easy","interpretation","distinguish_projection_actual","CBO's February 2026 baseline says the FY2026 deficit is projected at $1.9 trillion. Which wording is accurate?","CBO projects a $1.9 trillion FY2026 deficit",["The government has already realized a $1.9 trillion FY2026 deficit","Treasury collected a $1.9 trillion surplus","The current federal debt is $1.9 trillion"],"A baseline published before the fiscal year is complete reports a projection, not a realized result.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB9","easy","interpretation","distinguish_dated_debt_stock","Treasury's Debt to the Penny dataset, last updated August 26, 2026, reports daily U.S. dollar debt amounts. What does an observation dated August 25, 2026 represent?","A debt stock measured on that date, not a final fiscal-year deficit",["A completed fiscal-year deficit flow","A ten-year CBO projection","Federal revenues collected during August"],"Debt to the Penny records the outstanding debt stock on a specified date; it does not report an annual deficit.",{dataSourceKey:"TREASURY-DEBT-TO-PENNY"});
add("FB9","medium","calculation","interpret_cbo_budget_table","CBO's February 2026 baseline projects FY2026 revenues of $5.6 trillion and outlays of $7.4 trillion. Using the displayed rounded values, what approximate balance is implied?","About a $1.8 trillion deficit",["About a $1.8 trillion surplus","About a $13.0 trillion deficit","A balanced budget"],"The displayed values imply outlays exceed revenues by about $1.8 trillion; CBO separately reports a rounded deficit of $1.9 trillion.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB9","hard","integration","compare_cbo_projection_years","CBO's February 2026 baseline projects the deficit at 5.8 percent of GDP in 2026 and 6.7 percent in 2036. What is the change?","An increase of 0.9 percentage point",["An increase of 0.9 percent","An increase of 12.5 percentage points","A decrease of 0.9 percentage point"],"Subtracting the two projected shares gives 0.9 percentage point.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB9","elite","integration","evaluate_baseline_uncertainty","What does CBO's February 2026 baseline projection establish about the future?","It shows outcomes under stated assumptions and current-law conventions, not a guaranteed forecast",["It fixes future legislation","It reports realized Treasury results for every projected year","It eliminates uncertainty about interest rates"],"Baseline projections are conditional benchmarks whose outcomes can change with laws, economic conditions, and other developments.",{dataSourceKey:"CBO-2026-OUTLOOK"});
add("FB9","legendary","integration","align_debt_data_measures","A Treasury observation reports total public debt outstanding, while a CBO projection reports debt held by the public as a percentage of GDP. What must be aligned before comparing them?","Debt definition, observation date, actual-versus-projected status, and units",["Only the agency names","Only whether both numbers are positive","Nothing; all federal debt measures are interchangeable"],"A sound comparison requires the same measure, date/status, and units.",{dataSourceKey:"TREASURY-DEBT-TO-PENNY"});
add("FB9","legendary","integration","compare_projected_debt_ratios","CBO's February 2026 baseline projects debt held by the public at 101 percent of GDP in 2026 and 120 percent in 2036. Which conclusion is warranted?","The baseline projects the specified debt measure to rise relative to GDP",["The figures are realized debt totals in trillions of dollars","GDP is projected to fall by exactly 19 percent","Total public debt outstanding and debt held by the public are identical"],"The comparison is a projected ratio for debt held by the public, not a realized nominal total.",{dataSourceKey:"CBO-2026-OUTLOOK"});

export const productionQuestions = rows.map((row,index)=>({
  id: ID_FIRST+index,
  ...row,
  objectiveLabel:OBJECTIVES[row.objective],
  secondarySkills:[],
  repairSkill:row.primarySkill,
  conceptCluster:CONCEPT_ID,
  commonError:row.commonError||`Uses a neighboring rule instead of the evidence required by ${OBJECTIVES[row.objective]}.`,
  graphRequired:false,
  asset:null,
  sourceCurationPhase:PHASE
}));

if(productionQuestions.length!==108) throw new Error(`Expected 108 questions; found ${productionQuestions.length}.`);
if(productionQuestions.at(-1)?.id!==ID_LAST) throw new Error(`Expected final ID ${ID_LAST}.`);
const objectiveCounts=productionQuestions.reduce((o,q)=>(o[q.objective]=(o[q.objective]||0)+1,o),{});
for(const [objective,target] of Object.entries(OBJECTIVE_TARGETS)) if(objectiveCounts[objective]!==target) throw new Error(`${objective} expected ${target}; found ${objectiveCounts[objective]||0}.`);
const poolCounts=productionQuestions.reduce((o,q)=>(o[q.pool]=(o[q.pool]||0)+1,o),{});
const expectedPools={easy:20,medium:20,hard:18,elite:10,legendary:8,easyBoss:4,mediumBoss:4,finalBoss:4,legendaryBoss:4,repairQuestions:8,bridgeQuestions:8};
for(const [pool,target] of Object.entries(expectedPools)) if(poolCounts[pool]!==target) throw new Error(`${pool} expected ${target}; found ${poolCounts[pool]||0}.`);
if(productionQuestions.filter(q=>q.dataSourceKey).length!==15) throw new Error("Expected 15 official-data questions.");
if(productionQuestions.some(q=>q.graphRequired||q.asset)) throw new Error("Federal Budgets & Debt must remain graph-free.");
if(new Set(productionQuestions.map(q=>q.q.trim().toLowerCase())).size!==108) throw new Error("Duplicate authored stems detected.");
